160	<script>
161	  import router from '@system.router'
162	  import device from '@system.device'
163	
164	  // 手写补零（避免 padStart 的轻量运行时兼容风险）
165	  function pad2(n) {
166	    return n < 10 ? '0' + n : '' + n
167	  }
168	
169	  export default {
170	    private: {
171	      time: '00:00',
172	      timeTimer: null,
173	      statusbarHeight: 22,
174	      topBarPadTop: 0,
175	      showAppTitle: false,
176	      showRectTitle: true,
177	      screentype: 'rect',
178	      screenAdjusted: false,
179	      showKeyboard: false,
180	      searchQuery: '',
181	      displayList: [],
182	      totalCount: 0,
183	      currentPage: 1,
184	      pageSize: 20,
185	      loading: false,
186	      allLoaded: false,
187	      searched: false,
188	      activeCategory: 'all',
189	      activeRegion: 'all',
190	      searchTimer: null,
191	      isClearing: false,
192	      showEngineTip: false,
193	      // 无词进入时延迟到 screentype 确定后再自动弹键盘（避免 onInit 以默认 rect 渲染小键盘闪切）
194	      shouldOpenKeyboard: false,
195	      // 页面销毁标志：延迟弹键盘的回调到达时若已退出则跳过
196	      isDestroyed: false
197	    },
198	
199	    computed: {
200	      // 键盘打开时追加光标（与组件内部 caltext 的「_」光标一致，避免特殊字符缺字）
201	      displayQuery() {
202	        return this.searchQuery + (this.showKeyboard ? '_' : '')
203	      }
204	    },
205	
206	    onInit() {
207	      this.searchQuery = global.searchQuery || ''
208	      this.activeCategory = global.searchCategory || 'all'
209	      this.activeRegion = global.searchRegion || 'all'
210	      this.updateTime()
211	      this.timeTimer = setInterval(() => { this.updateTime() }, 30000)
212	      // 有词直接加载；无词等待弹键盘（延迟到 onShow 拿到 screentype 后再弹）
213	      if (this.searchQuery && this.searchQuery.trim()) {
214	        this.searched = true
215	        this.resetAndSearch()
216	      } else {
217	        // 不能在此立即 showKeyboard=true：onInit 时 DOM 未 ready、screentype 还是默认 'rect'，
218	        // 立即弹出会先渲染 rect 小键盘再切回正确形态（用户看到「打开瞬间缩小再变正常」）
219	        this.shouldOpenKeyboard = true
220	      }
221	      if (typeof global.addRuntimeLog === 'function') {
222	        global.addRuntimeLog('结果页打开，搜索词: ' + global.searchQuery, 'info')
223	      }
224	    },
225	
226	    // onShow 时 DOM 已 ready，获取屏幕信息做形态/安全偏移适配（仅执行一次）；
227	    // 若此前提示「未加载」而引擎现已就绪（用户去设置加载完返回），自动清除提示并重搜
228	    onShow() {
229	      var eng = global.searchEngine
230	      if (this.showEngineTip && eng && eng.isReady) {
231	        this.showEngineTip = false
232	        this.resetAndSearch()
233	      }
234	      if (this.screenAdjusted) return
235	      this.screenAdjusted = true
236	      this.adjustForScreen()
237	    },
238	
239	    onDestroy() {
240	      this.isDestroyed = true
241	      if (this.timeTimer) clearInterval(this.timeTimer)
242	      if (this.searchTimer) clearTimeout(this.searchTimer)
243	    },
244	
245	    updateTime() {
246	      var now = new Date()
247	      this.time = pad2(now.getHours()) + ':' + pad2(now.getMinutes())
248	    },
249	
250	    // 形态/安全偏移适配：状态栏高度 = 设计高 + 物理安全偏移换算的设计 px（同 index.ux）
251	    adjustForScreen() {
252	      var self = this
253	      device.getInfo({
254	        success: function(data) {
255	          var screenWidth = data.screenWidth
256	          var shape = data.screenShape
257	          var safeTopPx = 0
258	          var base = 22
259	          if (shape === 'pill-shaped') {
260	            safeTopPx = 12
261	            base = 50
262	          } else if (shape === 'circle') {
263	            safeTopPx = 10
264	            base = 26
265	          }
266	          var padTop = safeTopPx > 0 ? Math.round(safeTopPx * 300 / screenWidth) : 0
267	          self.topBarPadTop = padTop
268	          self.statusbarHeight = base + padTop
269	          self.showAppTitle = (shape === 'pill-shaped') || (shape === 'circle')
270	          self.showRectTitle = !self.showAppTitle
271	          self.screentype = shape === 'circle' ? 'circle' : shape === 'pill-shaped' ? 'pill-shaped' : 'rect'
272	          console.log('[RESULT] shape=' + shape + ' screentype=' + self.screentype + ' statusbarH=' + self.statusbarHeight)
273	          if (typeof global.addRuntimeLog === 'function') {
274	            global.addRuntimeLog('[RESULT] shape=' + shape + ' screentype=' + self.screentype, 'info')
275	          }
276	          // screentype 已确定，此刻 input-method(pill) 组件才刚开始 mount（构建 DOM + 加载键盘图），
277	          // 立即 showKeyboard 会与组件构建同帧导致弹出卡顿；延迟约 150ms 等组件就绪再弹出
278	          if (self.shouldOpenKeyboard) {
279	            self.shouldOpenKeyboard = false
280	            setTimeout(function() {
281	              if (self && !self.isDestroyed) {
282	                self.showKeyboard = true
283	              }
284	            }, 150)
285	          }
286	        },
287	        fail: function() {
288	          // getInfo 异常兜底：保持默认 rect，仍要完成无词自动弹键盘
289	          if (self.shouldOpenKeyboard) {
290	            self.shouldOpenKeyboard = false
291	            setTimeout(function() {
292	              if (self && !self.isDestroyed) {
293	                self.showKeyboard = true
294	              }
295	            }, 150)
296	          }
297	        }
298	      })
299	    },
300	
301	    // 点搜索框：开/收键盘，收起时触发搜索
302	    toggleKeyboard() {
303	      if (this.isClearing) return
304	      this.shouldOpenKeyboard = false // 用户已手动操作，getInfo 回调不再自动弹键盘
305	      this.showKeyboard = !this.showKeyboard
306	      if (!this.showKeyboard) {
307	        this.finishInput()
308	      }
309	    },
310	
311	    // 点「完成」：收起键盘并立即搜索
312	    finishInput() {
313	      this.showKeyboard = false
314	      this.resetAndSearch()
315	    },
316	
317	    // 清空关键词（清空时保持键盘打开状态，可继续输入）
318	    clearSearch() {
319	      this.isClearing = true
320	      this.searchQuery = ''
321	      global.searchQuery = ''
322	      this.displayList = []
323	      this.totalCount = 0
324	      this.currentPage = 1
325	      this.allLoaded = false
326	      this.searched = false
327	      var self = this
328	      setTimeout(function() { self.isClearing = false }, 200)
329	    },
330	
331	    // @complete：键盘逐字符提交（拼音候选/英文字母/空格），追加到关键词并实时搜索（防抖）
332	    onInput(evt) {
333	      var content = evt.detail.content
334	      if (content === undefined || content === null) return
335	      this.searchQuery += content
336	      global.searchQuery = this.searchQuery
337	      this.scheduleSearch()
338	    },
339	
340	    // @delete：键盘内部缓冲已空时，删除页面关键词末字符
341	    onDelete() {
342	      this.searchQuery = this.searchQuery.slice(0, -1)
343	      global.searchQuery = this.searchQuery
344	      this.scheduleSearch()
345	    },
346	
347	    // 防抖实时搜索（避免逐键触发）
348	    scheduleSearch() {
349	      var self = this
350	      if (this.searchTimer) clearTimeout(this.searchTimer)
351	      this.searchTimer = setTimeout(function() {
352	        self.resetAndSearch()
353	      }, 400)
354	    },
355	
356	    // 重置分页并搜索第 1 页
357	    resetAndSearch() {
358	      // 引擎未就绪（数据未加载）时提示用户去设置加载；
359	      // 注意：SearchEngine 的 isReady 是实例布尔属性（非方法），直接读布尔值
360	      var eng = global.searchEngine
361	      if (!eng || !eng.isReady) {
362	        this.showEngineTip = true
363	        this.displayList = []
364	        this.totalCount = 0
365	        this.currentPage = 1
366	        this.allLoaded = false
367	        this.searched = true
368	        return
369	      }
370	      this.showEngineTip = false
371	      if (!this.searchQuery || !this.searchQuery.trim()) {
372	        this.displayList = []
373	        this.totalCount = 0
374	        this.currentPage = 1
375	        this.allLoaded = false
376	        this.searched = false
377	        return
378	      }
379	      this.currentPage = 1
380	      this.allLoaded = false
381	      this.searched = true
382	      this.loadPage(1)
383	    },
384	
385	    async loadPage(page) {
386	      if (this.loading || this.allLoaded) return
387	      if (!this.searchQuery || !this.searchQuery.trim()) return
388	      this.loading = true
389	      try {
390	        var result = await global.searchHistory(this.searchQuery, {
391	          category: this.activeCategory,
392	          region: this.activeRegion,
393	          page: page,
394	          pageSize: this.pageSize
395	        })
396	        var formatted = (result.results || []).map(function(item) {
397	          // 取第一个关键词作为标题
398	          var title = item.title || '未知事件'
399	          if (title.indexOf(',') !== -1) {
400	            title = title.split(',')[0].trim()
401	          } else if (title.indexOf('，') !== -1) {
402	            title = title.split('，')[0].trim()
403	          }
404	          return {
405	            id: item.id || item._id,
406	            yearDisplay: item.yearDisplay || '未知',
407	            title: title,
408	            region: item.region || '未知'
409	          }
410	        })
411	        if (page === 1) {
412	          this.displayList = formatted
413	        } else {
414	          this.displayList = this.displayList.concat(formatted)
415	        }
416	        this.totalCount = result.total || 0
417	        this.currentPage = page
418	        this.loading = false
419	        if (formatted.length < this.pageSize) {
420	          this.allLoaded = true
421	        }
422	      } catch (e) {
423	        console.error('[loadPage] 错误:', e)
424	        this.loading = false
425	      }
426	    },
427	
