input.new_string:
.page-dot { width: 10px; height: 10px; border-radius: 5px; margin-bottom: 12px; }

/* ===== 搜索层（主页内嵌搜索，覆盖全屏） ===== */
.search-layer { position: absolute; left: 0; top: 0; width: 100%; height: 100%; background-color: #000000; z-index: 50; flex-direction: column; align-items: center; }

/* 搜索框：复用主页 .search-box/.search-box-icon 同名义尺寸；新增占位/输入/清空三件套 */
.search-wrap { position: relative; z-index: 30; flex-shrink: 0; }
.search-placeholder { font-size: 20px; color: #757575; flex: 1; margin-left: 10px; text-align: left; lines: 1; text-overflow: ellipsis; }
.search-input { font-size: 22px; color: #FFFFFF; flex: 1; margin-left: 10px; text-align: left; lines: 1; text-overflow: ellipsis; }
.clear-btn { width: 28px; height: 28px; border-radius: 14px; background-color: #3A3A3C; color: #FFFFFF; text-align: center; font-size: 18px; line-height: 28px; margin-right: 14px; flex-shrink: 0; }

/* 完成按钮：蓝色实心胶囊 */
.done-bar { position: relative; z-index: 30; width: 110px; height: 34px; border-radius: 17px; background-color: #4D9FEE; justify-content: center; align-items: center; margin-top: 8px; flex-shrink: 0; }
.done-text { font-size: 20px; color: #FFFFFF; font-weight: 700; }

.result-count { width: 100%; text-align: center; font-size: 16px; color: #757575; margin-top: 6px; flex-shrink: 0; }

/* 引擎未加载提示：黄色醒目，点击跳设置 */
.engine-tip { width: 100%; text-align: center; font-size: 18px; color: #FBBC05; margin-top: 8px; flex-shrink: 0; }

/* 结果列表 */
.result-area { width: 100%; flex: 1; flex-direction: column; }
.result-item { width: 94%; margin-left: 3%; border-radius: 14px; background-color: #1C1C1E; padding: 10px 14px; margin-bottom: 6px; flex-direction: column; flex-shrink: 0; }
.result-year { font-size: 20px; font-weight: bold; color: #4D9FEE; margin-bottom: 2px; }
.result-title { font-size: 22px; color: #FFFFFF; margin-bottom: 1px; lines: 1; text-overflow: ellipsis; }
.result-region { font-size: 17px; color: #757575; }

.empty-tip { width: 100%; text-align: center; font-size: 18px; color: #757575; margin-top: 40px; }
