417	    // 屏幕形态/安全偏移：状态栏高度 = 设计高 + 物理安全偏移换算的设计 px；
418	    // 分类行顶部固定在 designTop（设计 top 值），故其 margin-top 动态补偿；
419	    // 搜索按钮 margin-top = 屏设计高 - 顶部已占内容 - 按钮高 - 按钮底距屏底
420	    adjustForScreen() {
421	      var self = this
422	      device.getInfo({
423	        success: function(data) {
424	          var screenWidth = data.screenWidth
425	          var screenHeight = data.screenHeight
426	          var shape = data.screenShape
427	          var safeTopPx = 0
428	          var base = 22
429	          var iconW = 58
430	          var spacing = 17
431	          var count = 6
432	          var isCircle = false
433	          var guideText = '左右滑动 · 切换分类'
434	          // 布局常量（设计px）：screenH 屏设计高 / sbMT 搜索框margin-top / sbH 搜索框高 /
435	          // catScrollH 分类行高 / guideH 引导词(位于图标上方，含margin-top) / btnH 按钮高 / bottomGap 按钮底距屏底
436	          var screenH = 429
437	          var sbMT = 16
438	          var sbH = 56
439	          var catScrollH = 82
440	          var guideH = 25
441	          var btnH = 67
442	          var bottomGap = 14
443	          var padLeft = 8.5
444	          if (shape === 'pill-shaped') {
445	            safeTopPx = 12
446	            base = 50
447	            iconW = 95
448	            spacing = 55
449	            sbMT = 20
450	            sbH = 92
451	            catScrollH = 128
452	            guideH = 43
453	            btnH = 108
454	            bottomGap = 80
455	            padLeft = 27.5
456	          } else if (shape === 'circle') {
457	            safeTopPx = 10
458	            base = 26
459	            iconW = 41
460	            spacing = 8
461	            count = 5
462	            isCircle = true
463	            guideText = '轻触图标 · 浏览分类'
464	            sbMT = 10
465	            sbH = 36
466	            catScrollH = 58
467	            guideH = 19
468	            btnH = 66
469	            bottomGap = 12
470	            padLeft = 0
471	          }
472	          // 屏设计高动态计算（适配不同分辨率：小米九/小米十等同形态不同分辨率），缺失时 fallback 429
473	          if (screenHeight && screenHeight > 0) {
474	            screenH = Math.round(screenHeight * 300 / screenWidth)
475	          }
476	          var padTop = safeTopPx > 0 ? Math.round(safeTopPx * 300 / screenWidth) : 0
477	          self.topBarPadTop = padTop
478	          self.statusbarHeight = base + padTop
479	          self.screen1H = screenH
480	          self.isCircle = isCircle
481	          self.guideText = guideText
482	          // 应用名标题：胶囊/圆形显示（sb-block 内），矩形用独立居中 rect-title（显示在 statusbar 顶部中间）
483	          self.showAppTitle = (shape === 'pill-shaped') || (shape === 'circle')
484	          self.showRectTitle = !self.showAppTitle
485	          // 分类行位于引导词下方固定间距（图标整体下移、更贴近搜索按钮），确保搜索按钮完整显示
486	          // 矩形/胶囊/圆形 分别取 110 / 156 / 30
487	          var catsGap = 110
488	          if (shape === 'pill-shaped') catsGap = 156
489	          else if (shape === 'circle') catsGap = 30
490	          self.catsMarginTop = Math.max(0, catsGap)
491	          // 搜索按钮 margin-top = 屏设计高 - 顶部已占内容(状态栏+搜索框+分类行+引导词) - 按钮高 - 按钮底距屏底
492	          self.searchMarginTop = Math.max(0, screenH - (self.statusbarHeight + sbMT + sbH + self.catsMarginTop + catScrollH + guideH) - btnH - bottomGap)
493	          // 分页指示点竖直居中于两块之间（两个 10px 圆点 + 12px 间距，总高 32px）
494	          self.dotsTop = Math.round(screenH / 2) - 16
495	          self.snapParams = { iconW: iconW, spacing: spacing, count: count, padLeft: padLeft, enabled: count > 5 }
496	          // 诊断日志：记录形态与定位参数，便于实机排查
497	          console.log('[HOME] shape=' + shape + ' w=' + screenWidth + ' h=' + screenHeight + ' screenH=' + screenH + ' statusbarH=' + self.statusbarHeight + ' sbMT=' + sbMT + ' sbH=' + sbH + ' catsMT=' + self.catsMarginTop + ' searchMT=' + self.searchMarginTop)
498	          if (global.addRuntimeLog) {
499	            global.addRuntimeLog('[HOME] shape=' + shape + ' catsMT=' + self.catsMarginTop, 'info')
500	          }
501	          // 搜索层三形态键盘：由屏幕形状确定 screentype（同 result.ux）
502	          self.screentype = shape === 'circle' ? 'circle' : shape === 'pill-shaped' ? 'pill-shaped' : 'rect'
503	          // 无词进入搜索层时，screentype 已确定，此刻 input-method 组件才刚开始 mount（构建 DOM + 加载键盘图），
504	          // 立即 showKeyboard 会与组件构建同帧导致弹出卡顿；延迟约 150ms 等组件就绪再弹出，回调检查是否已销毁
505	          if (self.shouldOpenKeyboard) {
506	            self.shouldOpenKeyboard = false
507	            setTimeout(function() {
508	              if (self && !self.isDestroyed) {
509	                self.showKeyboard = true
