511	                if (typeof global.addRuntimeLog === 'function') {
512	                  global.addRuntimeLog('[HOME-SEARCH] 键盘开', 'info')
513	                }
514	              }
515	            }, 150)
516	          }
517	          if (isCircle) {
518	            self.displayCats = self.categories.slice(0, 5)
519	          } else {
520	            self.displayCats = self.categories
521	          }
522	        },
523	        fail: function() {
524	          // getInfo 异常兜底：保持默认 rect，仍要完成无词自动弹键盘
525	          if (self.shouldOpenKeyboard) {
526	            self.shouldOpenKeyboard = false
527	            setTimeout(function() {
528	              if (self && !self.isDestroyed) {
529	                self.showKeyboard = true
530	                console.log('[HOME-SEARCH] 键盘开')
