541	    // 整页滚动：实时更新当前页指示，停止（debounce 150ms）后吸附到最近的整屏位置
542	    onPageScroll(e) {
543	      var y = (e && e.scrollY) || 0
544	      this.lastPageY = y
545	      var h = this.screen1H || 429
546	      var page = Math.round(y / h)
547	      if (page < 0) page = 0
548	      if (page > 1) page = 1
549	      if (page !== this.curPage) this.curPage = page
550	      var self = this
551	      if (this.pageScrollTimer) clearTimeout(this.pageScrollTimer)
552	      this.pageScrollTimer = setTimeout(function() {
553	        self.snapPageScroll()
554	      }, 150)
555	    },
556	
557	    // 吸附到最近的整屏位置：目标 scrollY = page * 屏设计高
558	    snapPageScroll() {
559	      var h = this.screen1H || 429
560	      var y = this.lastPageY || 0
561	      var page = Math.round(y / h)
562	      if (page < 0) page = 0
563	      if (page > 1) page = 1
564	      this.curPage = page
565	      var target = page * h
566	      if (Math.abs(target - y) > 1) {
567	        var el = this.$element('pageScroll')
568	        if (el) {
569	          el.scrollTo({ left: 0, top: target, behavior: 'smooth' })
570	        }
571	      }
572	    },
573	
574	    // 分类横滑停止（debounce 150ms）后，把最近「两符号中点」对齐屏幕中心
575	    onCatScroll(e) {
576	      this.lastCatScrollX = (e && e.scrollX) || 0
577	      var self = this
578	      if (this.catScrollTimer) clearTimeout(this.catScrollTimer)
579	      this.catScrollTimer = setTimeout(function() {
580	        self.snapCatScroll()
581	      }, 150)
582	    },
583	
584	    // 步长法计算吸附目标：gap 中点 = padLeft + i*step + iconW + spacing/2（step = iconW + spacing），
585	    // 目标 scrollX = gap - 视口中心(150)，钳制到 [0, 内容宽(含左右 padLeft) - 视口宽]
586	    snapCatScroll() {
587	      var p = this.snapParams
588	      if (!p || !p.enabled) return
589	      var scrollEl = this.$element('catScroll')
590	      if (!scrollEl) return
591	      var curX = this.lastCatScrollX || 0
592	      var step = p.iconW + p.spacing
593	      var padLeft = p.padLeft || 0
594	      var viewportW = 300
595	      var maxX = Math.max(0, (2 * padLeft + p.count * p.iconW + (p.count - 1) * p.spacing) - viewportW)
596	      var viewCenter = viewportW / 2
597	      var bestX = 0
598	      var bestDist = Infinity
599	      for (var i = 0; i < p.count - 1; i++) {
600	        var gap = padLeft + i * step + p.iconW + p.spacing / 2
601	        var target = gap - viewCenter
602	        if (target < 0) target = 0
603	        if (target > maxX) target = maxX
604	        var dist = Math.abs(target - curX)
605	        if (dist < bestDist) {
606	          bestDist = dist
607	          bestX = target
608	        }
609	      }
610	      // 已在吸附位附近则不重复滚动，避免循环
611	      if (Math.abs(bestX - curX) > 1) {
612	        scrollEl.scrollTo({ left: bestX, top: 0, behavior: 'smooth' })
613	      }
614	    },
