772	          // 取第一个关键词作为标题
773	          var title = item.title || '未知事件'
774	          if (title.indexOf(',') !== -1) {
775	            title = title.split(',')[0].trim()
776	          } else if (title.indexOf('，') !== -1) {
777	            title = title.split('，')[0].trim()
778	          }
779	          return {
